service.method:

SELECT
		  USER_ID
		, MENU_PROFILE_CODE
		, USER_TYPE
FROM
	SUSMT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${COMPANY_CODE}	
	AND USER_ID 		= ${USER_ID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= ${POSITION}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${PHONE}
		, EMPLOYEE_NO       = ${SORT_KEY}
		, DEL_FLAG        	= ${DEL_FLAG}
		, LANGUAGE			= 'KO'
		, USER_TYPE			= #DB_OWNER#nvl($S{USER_TYPE}, USER_TYPE)
WHERE
	  HOUSE_CODE        	= ${session.HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


UPDATE SUSMT
SET
	DEL_FLAG = ${DEL_FLAG}
WHERE
		COMPANY_CODE  = ${COMPANY_CODE}
	AND USER_ID		  = ${USER_ID}


UPDATE BAT_UP_IMUSER
	SET
		 IF_FLAG	  = ${IF_RESULT}
WHERE
			COMPANY  = ${COMPANY_CODE}
		AND EMP_NO	 = ${USER_ID}
		AND INS_TIME = ${INS_TIME}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, COMPANY_CODE
		, PLANT_CODE
		, USER_NAME_LOC
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL		
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
		, EMPLOYEE_NO
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${USER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${COMPANY_CODE}
		, ${COMPANY_CODE}
		, ${USER_NAME_LOC}
		, ${PASSWORD}
		, ${DEPT}
		, ${POSITION}
		, ${EMAIL}				
		, 'KR'
		, 'A'
		, 'Z'
		, ${MENU_PROFILE_CODE}
		, 'A'
		, '0'
		, 'N'
		, ${DEL_FLAG}
		, '%Y/%m/%d'
		, ${PHONE}
		, 'KO'
		, ${SORT_KEY}
	)


UPDATE SCODE
SET
	  TEXT1		      = ${POSITION_LOC}
	, CHANGE_DATE     = ${current.DATE}
	, CHANGE_TIME     = ${current.TIME}
	, CHANGE_USER_ID  = ${session.ID}	
WHERE
	HOUSE_CODE        = ${session.HOUSE_CODE}
	AND TYPE 		      = 'UX049'
	AND CODE              = ${POSITION}
	AND LANGUAGE 		  = 'KO'


INSERT INTO SCODE (
	  HOUSE_CODE
	, TYPE 
	, CODE
	, LANGUAGE
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, USE_FLAG
	, TEXT1
	, DEL_FLAG
) VALUES (
	  ${session.HOUSE_CODE}
	, 'UX049'
	, ${POSITION}
	, 'KO'
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}				
	, 'Y'
	, ${POSITION_LOC}
	, 'N'
)
